SELECT ?point ?tsid ?class ?zone ?name WHERE {
  ?zone a brick:Zone .
  OPTIONAL { ?zone rdfs:label ?zonelab }
  ?point brick:hasProperty ?zone .
  ?point brick:hasType ?tc .
  ?point ref:hasTimeseriesId ?tsid .
}

SELECT ?z ?lab ?cls WHERE {
  ?z a brick:Zone .
  OPTIONAL { ?z rdfs:label ?lab }
  OPTIONAL { ?z a ?cls }
}

SELECT ?p ?lab ?cls ?tsid WHERE {
  ?p a ?cls .
  ?p brick:hasType ?tc .
  OPTIONAL { ?p rdfs:label ?lab }
  OPTIONAL { ?p ref:hasTimeseriesId ?tsid }
  FILTER (LCASE(STR(?cls)) || LCASE(STR(?tc)) LIKE "%light%" || LCASE(STR(?cls))||LCASE(STR(?tc)) LIKE "%pow%")
}

